# === 1-CLICK COLAB 8-WORKER BODYCAM UPLOADER (AUTO-REFRESHING TOKEN) ===
import os, sys, zlib, base64, subprocess, time, json, urllib.request, urllib.parse, threading

print("[1/3] Installing aria2, ffmpeg, rclone, yt-dlp, wgcf, wireproxy...")
subprocess.run("apt-get update -qq && apt-get install -y -qq aria2 ffmpeg rclone > /dev/null 2>&1 && pip install -q -U yt-dlp", shell=True)
os.makedirs("/root/.local/bin", exist_ok=True)
if not os.path.exists("/root/.local/bin/wgcf"):
    subprocess.run("curl -sL https://github.com/ViRb3/wgcf/releases/download/v2.2.22/wgcf_2.2.22_linux_amd64 -o /root/.local/bin/wgcf && chmod +x /root/.local/bin/wgcf", shell=True)
if not os.path.exists("/root/.local/bin/wireproxy"):
    subprocess.run("curl -sL https://github.com/pufferffish/wireproxy/releases/download/v1.0.9/wireproxy_linux_amd64.tar.gz | tar -xz -C /root/.local/bin wireproxy && chmod +x /root/.local/bin/wireproxy", shell=True)

print("[2/3] Writing rclone config, auto-refresh daemon, and 171-case payload...")
os.makedirs("/root/.config/rclone", exist_ok=True)
open("/root/.config/rclone/rclone.conf", "w").write(base64.b64decode("").decode())
open("/root/adc.json", "w").write(base64.b64decode("").decode())
open("/root/pure_171_cases_payload.json", "wb").write(zlib.decompress(base64.b64decode("")))
open("/root/worker_171_pure_cloud.py", "wb").write(zlib.decompress(base64.b64decode("")))

def token_refresher():
    while True:
        try:
            adc_data = json.load(open("/root/adc.json"))
            if "refresh_token" in adc_data:
                data = urllib.parse.urlencode({
                    "client_id": adc_data["client_id"],
                    "client_secret": adc_data["client_secret"],
                    "refresh_token": adc_data["refresh_token"],
                    "grant_type": "refresh_token"
                }).encode()
                req = urllib.request.Request("https://oauth2.googleapis.com/token", data=data)
                resp = json.loads(urllib.request.urlopen(req, timeout=15).read().decode())
                new_tok = resp["access_token"]
                new_exp = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() + 3500))
                new_rc = f'[gdrive2026_cases]\ntype = drive\nscope = drive\ntoken = {"access_token":"{new_tok}","token_type":"Bearer","expiry":"{new_exp}"}\nroot_folder_id = 11REjO5KBB5vWD8C6Xfid7HV1fkpWSBIB\n'
                open("/root/.config/rclone/rclone.conf", "w").write(new_rc)
        except Exception as e:
            pass
        time.sleep(1200)

threading.Thread(target=token_refresher, daemon=True).start()

print("[3/3] Launching 8-Worker Pipeline -> streaming live logs below...")
subprocess.run("pkill -f worker_171_pure_cloud.py || true", shell=True)
p = subprocess.Popen(["python3", "-u", "/root/worker_171_pure_cloud.py"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
